  .mem-search{flex:1;display:flex;align-items:center;gap:8px;background:var(--bg2);border:1px solid var(--line2);border-radius:10px;padding:9px 13px;color:var(--t3);font-size:13px}
  .mem-search input{flex:1;background:none;border:none;outline:none;color:var(--t1);font-size:13px;min-width:0}
