  await page.click('.proj-ws-pane[data-pane="luad"] .ws-sess');
  await page.waitForTimeout(250);
  const streamShown = await page.$eval('#chatStream', el => !el.classList.contains('hide'));
  console.log('5 ws 会话条目 → chatStream 可见:', streamShown);

